package com.lianxibu.site.controller.content;

import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static com.lianxibu.site.service.content.ReportInputFixtures.*;
import com.lianxibu.site.service.content.ReportInputSummaryReadService;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import tools.jackson.databind.node.ObjectNode;

class ReportInputSummaryControllerTest {
 private final Actor owner=new Actor("fictional-owner","owner");private IdentityService auth;private ReportInputSummaryReadService service;private MockMvc mvc;private ObjectProvider<ReportInputSummaryReadService> provider;
 @BeforeEach @SuppressWarnings("unchecked") void setup(){auth=mock(IdentityService.class);service=mock(ReportInputSummaryReadService.class);ObjectProvider<IdentityService> identity=mock(ObjectProvider.class);provider=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);when(provider.getIfAvailable()).thenReturn(service);when(auth.authenticate("fictional-session")).thenReturn(owner);mvc=MockMvcBuilders.standaloneSetup(new ReportInputSummaryController(identity,provider)).build();}
 @Test void ownerAuthenticationBeforeQueryAndService()throws Exception{mvc.perform(get(path()).param("unknown","fictional")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));when(auth.authenticate("fictional-session")).thenReturn(new Actor("fictional-user","user"));mvc.perform(get(path()).cookie(cookie()).param("input_snapshot_id","fictional-snapshot")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void queryIsClosedRequiredAndUnambiguous()throws Exception{mvc.perform(get(path()).cookie(cookie())).andExpect(status().isUnprocessableEntity());mvc.perform(get(path()).cookie(cookie()).param("input_snapshot_id","fictional-snapshot","fictional-other")).andExpect(status().isBadRequest());mvc.perform(request().param("unknown","fictional")).andExpect(status().isBadRequest());for(String value:List.of("0","51","01","1\n","9999999999999999"))mvc.perform(request().param("limit",value)).andExpect(status().isUnprocessableEntity());mvc.perform(request().param("cursor","")).andExpect(status().isUnprocessableEntity());verifyNoInteractions(service);}
 @Test void missingAssemblyAndTypedFailuresNoInternalData()throws Exception{when(provider.getIfAvailable()).thenReturn(null);mvc.perform(request()).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1"));when(provider.getIfAvailable()).thenReturn(service);for(RuntimeException failure:List.of(new ReportInputSummaryReadService.Missing(),new ReportInputSummaryReadService.SnapshotConflict(),new ReportInputSummaryReadService.CursorConflict(),new IllegalArgumentException("Fictional forbidden internal data"),new IllegalStateException("Fictional forbidden internal data"))){doThrow(failure).when(service).read(owner,"fictional-report","fictional-snapshot",null,20);int expected=failure instanceof ReportInputSummaryReadService.Missing?404:failure instanceof IllegalArgumentException?422:failure instanceof IllegalStateException?503:409;var result=mvc.perform(request()).andExpect(status().is(expected)).andReturn();assertFalse(result.getResponse().getContentAsString().contains("internal data"));}}
 @Test void actualServiceProjectsFrozenSummaryAndLegacyWithoutInternalBodies()throws Exception{when(provider.getIfAvailable()).thenReturn(new ReportInputSummaryReadService((r,s)->proof(r,s,root("daily",3)),key()));var result=mvc.perform(request().param("limit","1")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.total").value(3)).andExpect(jsonPath("$.data.items.length()").value(1)).andExpect(jsonPath("$.data.items[0].revision").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.input_cutoff_at").value("2026-02-02T01:00:00.000000Z")).andReturn();assertFalse(result.getResponse().getContentAsString().contains("internal body"));var legacy=root("daily",1);legacy.remove("report_summary_v1");when(provider.getIfAvailable()).thenReturn(new ReportInputSummaryReadService((r,s)->proof(r,s,legacy),key()));mvc.perform(request()).andExpect(status().isOk()).andExpect(jsonPath("$.data.reason").value("unproven_group_manifest")).andExpect(jsonPath("$.data.total").doesNotExist());mvc.perform(request().param("cursor","fictional-cursor")).andExpect(status().isUnprocessableEntity());}
 @Test void actualWholeEnvelopeOverOneMiBIsRejectedWithoutTruncation()throws Exception{var root=root("daily",20);for(var item:root.get("report_summary_v1").get("members"))((ObjectNode)item).put("summary","😀".repeat(16384));com.lianxibu.site.service.content.ReportInputProfile.validated(root);var actual=new ReportInputSummaryReadService((r,s)->proof(r,s,root),key());actual.read(owner,"fictional-report","fictional-snapshot",null,1);when(provider.getIfAvailable()).thenReturn(actual);mvc.perform(request()).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1")).andExpect(jsonPath("$.data").doesNotExist());var result=mvc.perform(request().param("limit","1")).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(20)).andExpect(jsonPath("$.data.items.length()").value(1)).andReturn();assertTrue(result.getResponse().getContentAsByteArray().length<1024*1024);assertEquals(16384,JSON.readTree(result.getResponse().getContentAsByteArray()).get("data").get("items").get(0).get("summary").textValue().codePointCount(0,32768));}
 private static String path(){return "/admin/reports/fictional-report/input-summary";}
 private static jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
 private static org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request(){return get(path()).cookie(cookie()).param("input_snapshot_id","fictional-snapshot");}
}
